/* Original exam practice, not a reproduction of textbook or instructor questions. */
(function(root){
 const topics={resultants:'Force resultants',geometry:'Position & unit vectors',projection:'Force projections',moments:'Moments & cross products',axis:'Axis moments',couples:'Couples'};
 const q=(id,topic,type,prompt,options,answer,explanation)=>({id,topic,type,prompt,options,answer,explanation});
 const tf=(id,topic,prompt,answer,explanation)=>q(id,topic,'tf',prompt,['True','False'],answer?0:1,explanation);
 const bank=[
 q('r1','resultants','mc','Two perpendicular forces have magnitudes <strong>120 N</strong> and <strong>90 N</strong>. What is the resultant magnitude?',['150 N','210 N','30 N','360 N'],0,'Perpendicular force components form a right triangle: <strong>√(120² + 90²) = 150 N</strong>. Adding magnitudes is valid only for forces pointing along the same direction.'),
 q('r2','resultants','mc','A <strong>100 N</strong> force is directed <strong>60° counterclockwise from +x</strong>. Which pair is (Fx, Fy)?',['(86.60, 50) N','(50, 86.60) N','(−50, 86.60) N','(100, 60) N'],1,'For this angle convention, <strong>Fx = F cos θ</strong> and <strong>Fy = F sin θ</strong>. Both components are positive in quadrant I.'),
 tf('r3','resultants','The resultant magnitude is always the <strong>sum of the individual force magnitudes</strong>.',false,'Forces have direction. Add <strong>signed components</strong> or use the included angle. The sum of magnitudes is the maximum, reached when both point in the same direction.'),
 tf('r4','resultants','In the <strong>graphical triangle rule for vector addition</strong>, the second vector can be translated to the first vector’s tip <strong>without rotating it</strong>.',true,'A translated vector keeps its magnitude and direction. The resultant runs from the first tail to the final tip. This statement concerns <strong>vector addition</strong>, not moving a physical force to a different line of action.'),
 q('g1','geometry','mc','A displacement is <strong>(3, 4, 0) m</strong>. Which is its unit vector?',['(3, 4, 0) m','(0.6, 0.8, 0) N','(0.6, 0.8, 0), unitless','(0.75, 1, 0), unitless'],2,'Its length is <strong>5 m</strong>. Divide every component by that same length. The metre units cancel, and the resulting vector has <strong>magnitude 1</strong>.'),
 q('g2','geometry','mc','Point <strong>A = (1, 2, −1) m</strong> and <strong>B = (4, 0, 3) m</strong>. What is rAB?',['(3, −2, 4) m','(−3, 2, −4) m','(5, 2, 2) m','(4, 0, 3) m'],0,'For <strong>A→B</strong>, subtract <strong>ending point minus starting point: B − A</strong>. The position of B alone works only when A is the origin.'),
 tf('g3','geometry','A <strong>unit vector</strong> has magnitude 1 and is <strong>dimensionless</strong>.',true,'A unit vector stores direction only. Multiply it by a force magnitude in N to obtain force components in N.'),
 tf('g4','geometry','The 3D coordinate direction angles <strong>α, β, and γ</strong> are all measured counterclockwise from <strong>+x</strong>.',false,'In 3D coordinate-direction notation, α is with <strong>+x</strong>, β with <strong>+y</strong>, and γ with <strong>+z</strong>. Each lies in 0–180°. This differs from a planar angle convention.'),
 q('p1','projection','mc','Force <strong>F = (100, 50, 0) N</strong> acts along an axis direction <strong>d = (3, 4, 0)</strong>. What is its signed scalar projection?',['500 N','100 N','111.80 N','50 N'],1,'Normalize d to <strong>u = (0.6, 0.8, 0)</strong>, then dot: <strong>100×0.6 + 50×0.8 = 100 N</strong>. Dotting with unnormalized d gives the wrong projection.'),
 q('p2','projection','mc','Force <strong>F = (−80, 60, 0) N</strong> is projected onto the <strong>positive x axis</strong>. What is the signed scalar projection?',['80 N','100 N','−80 N','60 N'],2,'The positive x-axis unit vector is (1, 0, 0). The signed projection is <strong>−80 N</strong>; its magnitude is 80 N.'),
 tf('p3','projection','Reversing the positive axis reverses the <strong>scalar projection’s sign</strong>, but leaves the <strong>projection vector unchanged</strong>.',true,'Both u and F·u reverse sign. Their product <strong>(F·u)u</strong> stays unchanged.'),
 tf('p4','projection','A force’s scalar projection can be found by dotting it with <strong>any unnormalized vector</strong> pointing along the axis.',false,'The axis vector must be <strong>normalized to magnitude 1</strong>. Otherwise, its arbitrary length scales the dot product.'),
 q('m1','moments','mc','For <strong>r = (2, 1, 0) m</strong> and <strong>F = (50, 100, 0) N</strong>, what is Mz?',['250 N·m','−150 N·m','150 N·m','200 N·m'],2,'Use <strong>Mz = rx Fy − ry Fx</strong>: 2×100 − 1×50 = <strong>150 N·m</strong>. Positive z corresponds to counterclockwise rotation viewed from +z.'),
 q('m2','moments','mc','In a <strong>right-handed Cartesian system</strong>, what is <strong>k × i</strong>?',['−j','j','i','0'],1,'The cyclic order is <strong>i × j = k, j × k = i, k × i = j</strong>. Reversing either pair negates the result.'),
 tf('m3','moments','Sliding a force along its <strong>same line of action on a rigid body</strong> preserves its moment about a fixed point.',true,'The change in position vector is parallel to F, and the cross product of parallel vectors is zero. The moment <strong>r × F</strong> is unchanged.'),
 tf('m4','moments','In <strong>|M| = Fd</strong>, d is always the distance from the reference point to the <strong>force application point</strong>.',false,'d is the <strong>perpendicular distance to the force’s infinite line of action</strong>. It equals the point-to-point distance only when the position vector is perpendicular to F.'),
 q('a1','axis','mc','A moment <strong>M = (0, 180, 0) N·m</strong> is given about a point on an axis with unit vector <strong>u = (0.6, 0.8, 0)</strong>. What is the signed axis moment?',['180 N·m','144 N·m','108 N·m','225 N·m'],1,'Project the moment: <strong>u·M = 0.6×0 + 0.8×180 = 144 N·m</strong>. The full vector magnitude is not the axis component.'),
 q('a2','axis','mc','To use <strong>Maxis = u·(r × F)</strong>, where should r begin?',['At any point, without adjustment','At the force tip','At a point on the specified axis','At the coordinate origin, even if it is off the axis'],2,'The reference point must <strong>lie on the specified axis</strong>. End r at a point on the force line. A moment about an off-axis point needs translation first.'),
 tf('a3','axis','A <strong>zero axis moment</strong> means the <strong>entire moment vector must be zero</strong>.',false,'A nonzero moment vector can be <strong>perpendicular to the axis</strong>, making its projection zero.'),
 tf('a4','axis','The sign of an axis moment is defined by the <strong>right-hand rule about the chosen positive axis</strong>.',true,'Choose the positive axis first. The signed scalar changes when that convention reverses; its magnitude does not.'),
 q('c1','couples','mc','Two equal and opposite <strong>100 N</strong> forces have <strong>2 m perpendicular line spacing</strong>. What is the couple magnitude?',['100 N·m','400 N·m','200 N·m','0 N·m'],2,'Use <strong>|Mc| = Fd = 100×2 = 200 N·m</strong>. Use the magnitude of one force, not twice that magnitude.'),
 q('c2','couples','mc','Two equal and opposite parallel forces act on <strong>different lines of action</strong>. Which statement is correct?',['Net force and moment are both zero','Net force is zero; couple moment can be nonzero','Net force is nonzero; moment is zero','The moment depends on the chosen reference point'],1,'A couple has <strong>zero resultant force</strong> but a <strong>nonzero turning moment</strong> when the force lines are separated.'),
 tf('c3','couples','A couple moment is <strong>independent of the reference point</strong> used to sum its two force moments.',true,'The reference-point terms cancel because <strong>F + (−F) = 0</strong>. The individual moments can change; their sum does not.'),
 tf('c4','couples','Two equal and opposite <strong>collinear forces</strong> necessarily produce a <strong>nonzero couple moment</strong>.',false,'Collinear forces have <strong>zero perpendicular line spacing</strong>, so the moment is zero.')
 ];
 function random(seed){let value=seed>>>0;return ()=>{value=(Math.imul(1664525,value)+1013904223)>>>0;return value/4294967296;};}
 function shuffle(items,rng){const values=[...items];for(let i=values.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[values[i],values[j]]=[values[j],values[i]];}return values;}
 function sample(type,rng,count){const pool=bank.filter(q=>q.type===type),chosen=Object.keys(topics).map(topic=>{const options=pool.filter(q=>q.topic===topic);return options[Math.floor(rng()*options.length)];}),extra=shuffle(pool.filter(q=>!chosen.includes(q)),rng).slice(0,count-6);return shuffle([...chosen,...extra],rng).map(q=>q.id);}
 function calculations(seed,version=2){const rng=random(seed),M=root.StudyMath||(typeof require!=='undefined'?require('./math.js'):null),useSimple=rng()<.5,a=useSimple?80:120,b=useSimple?60:90,alpha=useSimple?0:30,beta=useSimple?90:120,result=M.resultant(a,alpha,b,beta),field=(id,label,value,points,tolerance)=>({id,label,value,points,tolerance});
 const resultant={id:'calc-resultant',topic:'resultants',title:'Calculation 1 · Resultant force',prompt:`Two forces act at the same point: <strong>A = ${a} N at ${alpha}°</strong> and <strong>B = ${b} N at ${beta}°</strong>, measured counterclockwise from +x. Use the <strong>parallelogram law</strong> for the magnitude, then find the Cartesian components and direction. Sketch the parallelogram on paper.`,fields:[field('rx','Rx (N)',result.x,5,.1),field('ry','Ry (N)',result.y,5,.1),field('magnitude','Resultant magnitude (N)',result.magnitude,5,.1),field('angle','Direction from +x (0–360°)',result.angle,5,.2)],geometry:{kind:'resultant',a,b,alpha,beta},steps:[`The tail-to-tail included angle is <strong>${beta-alpha}°</strong>. Parallelogram law: R = √(A² + B² + 2AB cos φ).`,`Rx = A cos α + B cos β = <strong>${result.x.toFixed(4)} N</strong>. Ry = A sin α + B sin β = <strong>${result.y.toFixed(4)} N</strong>.`,`R = <strong>${result.magnitude.toFixed(4)} N</strong>. Direction θ = atan2(Ry, Rx) = <strong>${result.angle.toFixed(4)}°</strong>, counterclockwise from +x.`]};
 const spatial=rng()<.5,P=spatial?[2,0,0]:[1,2,0],Q=spatial?[2,3,4]:[4,6,0],forceMagnitude=spatial?350:250,directed=M.directedForce(P,Q,forceMagnitude),moment=M.moment([0,0,0],P,directed.force),tuple=v=>'('+v.map(n=>Number(n.toFixed(4))).join(', ')+')';
 const cable={id:'calc-cable',topic:'moments',title:'Calculation 2 · Cable force and moment',prompt:`A cable exerts <strong>${forceMagnitude} N</strong> at <strong>P = ${tuple(P)} m</strong>, pulling toward <strong>Q = ${tuple(Q)} m</strong>. Find the Cartesian force and its moment about <strong>O = (0, 0, 0) m</strong> using the <strong>cross product</strong>.`,fields:[...directed.force.map((v,i)=>field('f'+i,'F'+['x','y','z'][i]+' (N)',v,2,.1)),...moment.components.map((v,i)=>field('m'+i,'M'+['x','y','z'][i]+' (N·m)',v,3,.1)),field('magnitude','Moment magnitude (N·m)',moment.magnitude,5,.1)],geometry:{kind:'cable',P,Q},steps:[`rPQ = Q − P = <strong>${tuple(directed.displacement)} m</strong>; length = <strong>${directed.length.toFixed(4)} m</strong>.`,`uPQ = rPQ / |rPQ| = <strong>${tuple(directed.unit)}</strong>, dimensionless. F = ${forceMagnitude} uPQ = <strong>${tuple(directed.force)} N</strong>.`,`The moment position vector is <strong>rOP = P − O = ${tuple(P)} m</strong>, not rPQ.`,`M = rOP × F = <strong>${tuple(moment.components)} N·m</strong>. Its magnitude is <strong>${moment.magnitude.toFixed(4)} N·m</strong>.`]};
 const axisCase=rng()<.5,sign=rng()<.5?1:-1;let third;
 {const mv=[0,180*sign,0],axis=M.axisMoment([0,0,0],[3,4,0],mv);third={id:'calc-axis',topic:'axis',title:'Calculation 3 · Moment about a rod',prompt:`The moment about <strong>A = (0, 0, 0) m</strong> is <strong>MA = ${tuple(mv)} N·m</strong>. Rod AB ends at <strong>B = (3, 4, 0) m</strong>. Find its unit vector, the <strong>signed moment about A→B</strong>, and the <strong>axis moment magnitude</strong>.`,fields:[...axis.unit.map((v,i)=>field('u'+i,'u'+['x','y','z'][i]+' (unitless)',v,2,.005)),field('scalar','Signed axis moment (N·m)',axis.scalar,7,.1),field('magnitude','Axis moment magnitude (N·m)',axis.magnitude,7,.1)],geometry:{kind:'axis',A:[0,0,0],B:[3,4,0]},steps:['uAB = (B − A)/|B − A| = <strong>(0.6, 0.8, 0)</strong>.',`Maxis = uAB·MA = 0.6×0 + 0.8×(${180*sign}) + 0×0 = <strong>${axis.scalar} N·m</strong>.`,`Magnitude = |Maxis| = <strong>${axis.magnitude} N·m</strong>. Preserve the sign only for the signed result.`]};}
 const axisProblem=third;{const F=[0,100*sign,0],P=[2,3,0],Q=[0,0,0],couple=M.couple(P,Q,F);third={id:'calc-couple',topic:'couples',title:version===1?'Calculation 3 · Couple moment':'Calculation 4 · Couple moment',prompt:`Force <strong>+F = ${tuple(F)} N</strong> acts at <strong>P = (2, 3, 0) m</strong>, and <strong>−F</strong> acts at <strong>Q = (0, 0, 0) m</strong>. Find the couple vector, its magnitude, and the <strong>perpendicular force-line spacing</strong>.`,fields:[...couple.components.map((v,i)=>field('m'+i,'Mc'+['x','y','z'][i]+' (N·m)',v,3,.1)),field('magnitude','Couple magnitude (N·m)',couple.magnitude,6,.1),field('arm','Perpendicular spacing d (m)',couple.arm,5,.01)],geometry:{kind:'couple',P,Q,F},steps:['Net force is <strong>zero</strong>. Choose separation from −F to +F: rQP = P − Q = <strong>(2, 3, 0) m</strong>.',`Mc = rQP × F = <strong>${tuple(couple.components)} N·m</strong>; magnitude = <strong>${couple.magnitude} N·m</strong>.`,`d = |Mc|/|F| = ${couple.magnitude}/100 = <strong>2 m</strong>. The point spacing √13 m is not the perpendicular line spacing.`]};}
 return version===1?[resultant,cable,axisCase?axisProblem:third]:[resultant,cable,axisProblem,third];}
 function createAttempt(seed,now=Date.now()){const rng=random(seed);return {version:2,seed:seed>>>0,startedAt:now,deadline:now+120*60*1000,status:'active',mc:sample('mc',rng,7),tf:sample('tf',rng,6),answers:{},work:{},flags:[],index:0};}
 function remaining(attempt,now=Date.now()){return Math.max(0,attempt.deadline-now);}
 function questions(attempt){return [...attempt.mc,...attempt.tf].map(id=>bank.find(q=>q.id===id));}
 function conceptPoints(attempt,question){return attempt.version===1?(question.type==='mc'?3:2):20/13;}
 function grade(attempt){let score=0;const concepts=questions(attempt).map(question=>{const answer=attempt.answers[question.id],correct=answer!==undefined&&Number(answer)===question.answer,points=conceptPoints(attempt,question);if(correct)score+=points;return {question,answer,correct,earned:correct?points:0,points};});const problems=calculations(attempt.seed,attempt.version).map(problem=>{let earned=0;const fields=problem.fields.map(field=>{const raw=attempt.answers[problem.id]?.[field.id],hasAnswer=raw!==undefined&&String(raw).trim()!==''&&Number.isFinite(Number(raw)),correct=hasAnswer&&Math.abs(Number(raw)-field.value)<=field.tolerance;if(correct)earned+=field.points;return {...field,answer:raw,correct,earned:correct?field.points:0};});score+=earned;return {problem,fields,earned,points:20};});return {score:Number(score.toFixed(8)),total:100,concepts,problems};}
 const api={topics,bank,calculations,createAttempt,remaining,questions,conceptPoints,grade};if(typeof module!=='undefined')module.exports=api;else root.AssessmentData=api;
})(typeof window!=='undefined'?window:globalThis);
